import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 32 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time


def _build(r, rows):
    """Build hex packing for radius r with given row counts. Return (N,3) array."""
    circles = []
    dy = np.sqrt(3.0) * r
    for k, n in enumerate(rows):
        y = r + k * dy
        x0 = 0.5 - (n - 1) * r
        for i in range(n):
            x = x0 + i * 2.0 * r
            circles.append((x, y, r))
    return np.array(circles, dtype=float)


def _valid(r, rows):
    if r <= 0:
        return False
    c = _build(r, rows)
    # inside square
    if np.any(c[:, 0] - c[:, 2] < -1e-12) or np.any(c[:, 0] + c[:, 2] > 1 + 1e-12):
        return False
    if np.any(c[:, 1] - c[:, 2] < -1e-12) or np.any(c[:, 1] + c[:, 2] > 1 + 1e-12):
        return False
    # pairwise
    n = c.shape[0]
    for i in range(n):
        for j in range(i + 1, n):
            dx = c[i, 0] - c[j, 0]
            dy = c[i, 1] - c[j, 1]
            d = np.hypot(dx, dy)
            if d < c[i, 2] + c[j, 2] - 1e-12:
                return False
    return True


def construct(budget_seconds, start):
    t0 = time.process_time()
    rows = [6, 5, 6, 5, 6, 4]
    assert sum(rows) == 32

    lo, hi = 0.0, 0.2
    # binary search largest valid r
    for _ in range(80):
        mid = 0.5 * (lo + hi)
        if _valid(mid, rows):
            lo = mid
        else:
            hi = mid
        if time.process_time() - t0 > budget_seconds * 0.5:
            break

    r = lo
    best = _build(r, rows)

    # Safety: shrink slightly to guarantee strict validity
    best[:, 2] *= (1.0 - 1e-9)
    # Also ensure centers stay inside with shrunk radius (they will, since r smaller)
    # Clamp tiny numerical issues
    for i in range(best.shape[0]):
        x, y, rr = best[i]
        x = min(max(x, rr), 1.0 - rr)
        y = min(max(y, rr), 1.0 - rr)
        best[i] = (x, y, rr)

    # If start is better, keep it
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.shape == (32, 3) and s[:, 2].sum() > best[:, 2].sum():
            return s

    return best

import numpy as np
import time
from scipy.optimize import minimize


def _hex_layout(n_rows, n_cols_list):
    """Hexagonal-ish layout with given row counts."""
    pts = []
    r0 = 0.5 / max(n_rows, max(n_cols_list))
    for j, ncol in enumerate(n_cols_list):
        y = (j + 0.5) / n_rows
        for i in range(ncol):
            x = (i + 0.5) / ncol
            pts.append((x, y))
    return np.array(pts)


def _inflate(start, r):
    pts = np.asarray(start, dtype=float)[:, :2]
    return np.hstack([pts, np.full((len(pts), 1), r)])


def _random_feasible(n, rng):
    pts = []
    tries = 0
    while len(pts) < n and tries < 100000:
        tries += 1
        x, y = rng.random(), rng.random()
        ok = True
        for (px, py) in pts:
            if (x - px) ** 2 + (y - py) ** 2 < (0.01) ** 2:
                ok = False
                break
        if ok:
            pts.append((x, y))
    while len(pts) < n:
        pts.append((rng.random(), rng.random()))
    return np.array(pts)


def _greedy_insert(n, rng):
    """Greedy: place circles one by one maximizing radius."""
    circles = []  # (x,y,r)
    for _ in range(n):
        best = None
        best_r = -1
        for _t in range(400):
            x, y = rng.random(), rng.random()
            r = min(x, 1 - x, y, 1 - y)
            for (cx, cy, cr) in circles:
                d = np.hypot(x - cx, y - cy)
                r = min(r, d - cr)
            if r > best_r:
                best_r = r
                best = (x, y, r)
        if best is None or best_r <= 0:
            best = (0.5, 0.5, 0.001)
        circles.append(best)
    return np.array(circles)


def _pack_vec(z, n):
    return z[:2 * n].reshape(n, 2), z[2 * n:]


def _objective(z, n):
    return -np.sum(z[2 * n:])


def _constraints(z, n):
    xy, r = _pack_vec(z, n)
    cons = []
    # walls
    cons.append(xy[:, 0] - r)
    cons.append(1 - xy[:, 0] - r)
    cons.append(xy[:, 1] - r)
    cons.append(1 - xy[:, 1] - r)
    # pairwise
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(xy[i, 0] - xy[j, 0], xy[i, 1] - xy[j, 1])
            cons.append(d - r[i] - r[j])
    return np.concatenate(cons)


def _slsqp(init, n, time_limit):
    xy0 = init[:, :2].copy()
    r0 = init[:, 2].copy()
    # clamp initial to feasible-ish
    r0 = np.maximum(r0, 1e-4)
    for i in range(n):
        r0[i] = min(r0[i], xy0[i, 0], 1 - xy0[i, 0], xy0[i, 1], 1 - xy0[i, 1])
    z0 = np.concatenate([xy0.ravel(), r0])
    bounds = [(0, 1)] * (2 * n) + [(1e-6, 0.5)] * n
    cons = {'type': 'ineq', 'fun': _constraints, 'args': (n,)}
    try:
        res = minimize(_objective, z0, args=(n,), method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': 300, 'ftol': 1e-12})
        xy, r = _pack_vec(res.x, n)
        return np.hstack([xy, r.reshape(-1, 1)])
    except Exception:
        return init


def _validate_and_shrink(sol):
    sol = np.asarray(sol, dtype=float).copy()
    n = len(sol)
    # shrink radii to guarantee feasibility
    for i in range(n):
        x, y, r = sol[i]
        r = min(r, x, 1 - x, y, 1 - y)
        sol[i, 2] = max(r, 0)
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(sol[i, 0] - sol[j, 0], sol[i, 1] - sol[j, 1])
            s = sol[i, 2] + sol[j, 2]
            if d < s:
                # shrink both
                excess = (s - d) / 2 + 1e-12
                sol[i, 2] = max(sol[i, 2] - excess, 1e-9)
                sol[j, 2] = max(sol[j, 2] - excess, 1e-9)
    sol[:, 2] = np.maximum(sol[:, 2] - 1e-9, 1e-9)
    return sol


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)

    starts = []
    # 1. hex [6,5,6,5,6,4]
    hex_pts = _hex_layout(6, [6, 5, 6, 5, 6, 4])
    if len(hex_pts) >= n:
        hex_pts = hex_pts[:n]
    else:
        hex_pts = np.vstack([hex_pts, _random_feasible(n - len(hex_pts), rng)])
    starts.append(np.hstack([hex_pts, np.full((n, 1), 0.08)]))

    # 2. p0001 inflated to r=0.08
    if start is not None:
        starts.append(_inflate(start, 0.08))
    else:
        k = int(np.ceil(np.sqrt(n)))
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        starts.append(np.hstack([np.array(pts), np.full((n, 1), 0.08)]))

    # 3. random feasible
    rf = _random_feasible(n, rng)
    starts.append(np.hstack([rf, np.full((n, 1), 0.05)]))

    # 4. greedy insertion
    g = _greedy_insert(n, rng)
    starts.append(g)

    # 5. perturbed hex
    ph = hex_pts + rng.normal(0, 0.02, hex_pts.shape)
    ph = np.clip(ph, 0.02, 0.98)
    starts.append(np.hstack([ph, np.full((n, 1), 0.08)]))

    best = None
    best_score = -1
    n_starts = len(starts)
    for idx, s in enumerate(starts):
        elapsed = time.process_time() - t0
        remaining = budget_seconds - elapsed
        if remaining <= 0.3:
            break
        # allocate remaining time across remaining starts
        slice_t = remaining / (n_starts - idx)
        sol = _slsqp(s, n, slice_t)
        sol = _validate_and_shrink(sol)
        score = sol[:, 2].sum()
        if score > best_score:
            best_score = score
            best = sol

    if best is None:
        if start is not None:
            best = _validate_and_shrink(start)
        else:
            best = _validate_and_shrink(starts[0])

    print(f"best score {best[:,2].sum():.6f}")
    return best

import numpy as np
import time
from scipy.optimize import minimize


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    def unpack(v):
        return v[0::3].copy(), v[1::3].copy(), v[2::3].copy()

    def pack(x, y, r):
        v = np.zeros(3 * n)
        v[0::3] = x
        v[1::3] = y
        v[2::3] = r
        return v

    def make_cons():
        cons = []
        for i in range(n):
            def c1(v, i=i):
                return v[3*i] - v[3*i+2]
            def c1g(v, i=i):
                g = np.zeros_like(v); g[3*i] = 1.0; g[3*i+2] = -1.0; return g
            cons.append({'type': 'ineq', 'fun': c1, 'jac': c1g})
            def c2(v, i=i):
                return 1.0 - v[3*i] - v[3*i+2]
            def c2g(v, i=i):
                g = np.zeros_like(v); g[3*i] = -1.0; g[3*i+2] = -1.0; return g
            cons.append({'type': 'ineq', 'fun': c2, 'jac': c2g})
            def c3(v, i=i):
                return v[3*i+1] - v[3*i+2]
            def c3g(v, i=i):
                g = np.zeros_like(v); g[3*i+1] = 1.0; g[3*i+2] = -1.0; return g
            cons.append({'type': 'ineq', 'fun': c3, 'jac': c3g})
            def c4(v, i=i):
                return 1.0 - v[3*i+1] - v[3*i+2]
            def c4g(v, i=i):
                g = np.zeros_like(v); g[3*i+1] = -1.0; g[3*i+2] = -1.0; return g
            cons.append({'type': 'ineq', 'fun': c4, 'jac': c4g})
        for i in range(n):
            for j in range(i + 1, n):
                def cp(v, i=i, j=j):
                    dx = v[3*i] - v[3*j]
                    dy = v[3*i+1] - v[3*j+1]
                    rs = v[3*i+2] + v[3*j+2]
                    return dx*dx + dy*dy - rs*rs
                def cpg(v, i=i, j=j):
                    g = np.zeros_like(v)
                    dx = v[3*i] - v[3*j]
                    dy = v[3*i+1] - v[3*j+1]
                    rs = v[3*i+2] + v[3*j+2]
                    g[3*i] = 2*dx; g[3*j] = -2*dx
                    g[3*i+1] = 2*dy; g[3*j+1] = -2*dy
                    g[3*i+2] = -2*rs; g[3*j+2] = -2*rs
                    return g
                cons.append({'type': 'ineq', 'fun': cp, 'jac': cpg})
        return cons

    cons = make_cons()
    bounds = [(0.0, 1.0)] * (3 * n)
    for i in range(n):
        bounds[3*i+2] = (1e-6, 0.5)

    def obj_max(v):
        return -np.sum(v[2::3])

    def obj_max_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    # initial point
    if start is not None and np.asarray(start).shape == (n, 3):
        s = np.asarray(start, dtype=float)
        v = pack(s[:, 0].copy(), s[:, 1].copy(), s[:, 2].copy())
    else:
        k = 6
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        x0 = np.zeros(3 * n)
        for idx, (x, y) in enumerate(pts):
            x0[3 * idx] = x
            x0[3 * idx + 1] = y
            x0[3 * idx + 2] = 0.08
        v = x0

    def best_score(vv):
        return np.sum(vv[2::3])

    # inflation/projection loop
    rng = np.random.default_rng(12345)
    best_v = v.copy()
    best_s = best_score(best_v)

    def time_left():
        return budget_seconds - (time.process_time() - t0)

    for it in range(25):
        if time_left() < 1.5:
            break
        x, y, r = unpack(best_v)
        # target radii: inflate, capped by wall distances
        cap = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))
        r0 = np.minimum(1.03 * r, cap)
        r0 = np.maximum(r0, 1e-6)
        v0 = pack(x, y, r0)

        def obj_proj(vv):
            d = vv - v0
            return np.sum(d * d)

        def obj_proj_grad(vv):
            return 2.0 * (vv - v0)

        try:
            res = minimize(obj_proj, best_v.copy(), jac=obj_proj_grad, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': 200, 'ftol': 1e-12})
            cand = res.x
            # ensure feasibility-ish
            if np.all(np.isfinite(cand)):
                cs = best_score(cand)
                if cs > best_s + 1e-10:
                    best_v = cand
                    best_s = cs
        except Exception:
            pass

    # final maximisation
    if time_left() > 0.5:
        try:
            res = minimize(obj_max, best_v, jac=obj_max_grad, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': 1000, 'ftol': 1e-12})
            cand = res.x
            if np.all(np.isfinite(cand)) and best_score(cand) > best_s:
                best_v = cand
                best_s = best_score(cand)
        except Exception:
            pass

    x, y, r = unpack(best_v)
    r = np.maximum(r - 1e-9, 1e-12)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    out = np.column_stack([x, y, r])

    # repair overlaps
    for _ in range(50):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
                s = out[i, 2] + out[j, 2]
                if d < s:
                    bad = True
                    excess = s - d
                    out[i, 2] -= excess / 2 + 1e-12
                    out[j, 2] -= excess / 2 + 1e-12
        if not bad:
            break

    out[:, 2] = np.maximum(out[:, 2], 1e-12)
    # final wall clamp
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    return out

import numpy as np
import time
from scipy.optimize import minimize


def _build_constraints(n):
    cons = []
    for i in range(n):
        def c1(v, i=i):
            return v[3*i] - v[3*i+2]
        def c1g(v, i=i):
            g = np.zeros_like(v); g[3*i] = 1.0; g[3*i+2] = -1.0; return g
        cons.append({'type': 'ineq', 'fun': c1, 'jac': c1g})
        def c2(v, i=i):
            return 1.0 - v[3*i] - v[3*i+2]
        def c2g(v, i=i):
            g = np.zeros_like(v); g[3*i] = -1.0; g[3*i+2] = -1.0; return g
        cons.append({'type': 'ineq', 'fun': c2, 'jac': c2g})
        def c3(v, i=i):
            return v[3*i+1] - v[3*i+2]
        def c3g(v, i=i):
            g = np.zeros_like(v); g[3*i+1] = 1.0; g[3*i+2] = -1.0; return g
        cons.append({'type': 'ineq', 'fun': c3, 'jac': c3g})
        def c4(v, i=i):
            return 1.0 - v[3*i+1] - v[3*i+2]
        def c4g(v, i=i):
            g = np.zeros_like(v); g[3*i+1] = -1.0; g[3*i+2] = -1.0; return g
        cons.append({'type': 'ineq', 'fun': c4, 'jac': c4g})
    for i in range(n):
        for j in range(i + 1, n):
            def cp(v, i=i, j=j):
                dx = v[3*i] - v[3*j]
                dy = v[3*i+1] - v[3*j+1]
                rs = v[3*i+2] + v[3*j+2]
                return dx*dx + dy*dy - rs*rs
            def cpg(v, i=i, j=j):
                g = np.zeros_like(v)
                dx = v[3*i] - v[3*j]
                dy = v[3*i+1] - v[3*j+1]
                rs = v[3*i+2] + v[3*j+2]
                g[3*i] = 2*dx; g[3*j] = -2*dx
                g[3*i+1] = 2*dy; g[3*j+1] = -2*dy
                g[3*i+2] = -2*rs; g[3*j+2] = -2*rs
                return g
            cons.append({'type': 'ineq', 'fun': cp, 'jac': cpg})
    return cons


def _obj(v):
    return -np.sum(v[2::3])


def _obj_grad(v):
    g = np.zeros_like(v)
    g[2::3] = -1.0
    return g


def _clean(out, n):
    out = out.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-12)
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    for _ in range(50):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(out[i,0]-out[j,0], out[i,1]-out[j,1])
                s = out[i,2] + out[j,2]
                if d < s:
                    bad = True
                    excess = s - d
                    out[i,2] -= excess/2 + 1e-12
                    out[j,2] -= excess/2 + 1e-12
        if not bad:
            break
    out[:, 2] = np.maximum(out[:, 2], 1e-12)
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    return out


def _valid(out, n):
    for i in range(n):
        x, y, r = out[i]
        if r <= 0:
            return False
        if x - r < -1e-12 or x + r > 1 + 1e-12:
            return False
        if y - r < -1e-12 or y + r > 1 + 1e-12:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(out[i,0]-out[j,0], out[i,1]-out[j,1])
            if d < out[i,2] + out[j,2] - 1e-12:
                return False
    return True


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    cons = _build_constraints(n)
    bounds = [(0.0, 1.0)] * (3 * n)
    for i in range(n):
        bounds[3*i+2] = (1e-6, 0.5)

    best_out = None
    best_score = -1.0

    def consider(v):
        nonlocal best_out, best_score
        x, y, r = v[0::3], v[1::3], v[2::3]
        out = np.column_stack([x, y, r])
        out = _clean(out, n)
        if _valid(out, n):
            s = float(np.sum(out[:, 2]))
            if s > best_score:
                best_score = s
                best_out = out

    # Include start as a candidate
    if start is not None:
        try:
            s = np.asarray(start, dtype=float)
            if s.shape == (n, 3):
                consider(s.reshape(-1))
        except Exception:
            pass

    # Grid-derived start (as in base)
    k = 6
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
    x0 = np.zeros(3 * n)
    for idx, (x, y) in enumerate(pts):
        x0[3*idx] = x
        x0[3*idx+1] = y
        x0[3*idx+2] = 0.08

    rng = np.random.default_rng(12345)

    def run_slsqp(v0, maxiter):
        try:
            res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                           constraints=cons, bounds=bounds,
                           options={'maxiter': maxiter, 'ftol': 1e-12})
            return res.x
        except Exception:
            return None

    # First: polish the base grid start
    v = run_slsqp(x0, 500)
    if v is not None:
        consider(v)

    # Random restarts
    n_restarts = 20
    for it in range(n_restarts):
        elapsed = time.process_time() - t0
        remaining = budget_seconds - elapsed
        if remaining < 0.5:
            break
        v0 = np.zeros(3 * n)
        v0[0::3] = rng.uniform(0.1, 0.9, n)
        v0[1::3] = rng.uniform(0.1, 0.9, n)
        v0[2::3] = 0.02
        v = run_slsqp(v0, 500)
        if v is not None:
            consider(v)

    if best_out is None:
        # fallback: grid with small radius
        out = np.zeros((n, 3))
        for idx, (x, y) in enumerate(pts):
            out[idx] = (x, y, 0.08)
        out = _clean(out, n)
        return out

    return best_out

import numpy as np
import time
from scipy.optimize import minimize


def _feasible_radius(cx, cy, present, n):
    r = min(cx, 1.0 - cx, cy, 1.0 - cy)
    for (px, py, pr) in present:
        d = np.hypot(cx - px, cy - py)
        r = min(r, d - pr)
    return r


def _slsqp_polish(s, n, iters, ftol=1e-14):
    r0 = np.clip(s[:, 2], 1e-6, 0.49)
    denom = 1.0 - 2.0 * r0
    denom = np.where(np.abs(denom) < 1e-9, 1e-9, denom)
    u0 = np.clip((s[:, 0] - r0) / denom, 0.0, 1.0)
    v0 = np.clip((s[:, 1] - r0) / denom, 0.0, 1.0)

    x0 = np.zeros(3 * n)
    x0[0::3] = u0
    x0[1::3] = v0
    x0[2::3] = r0

    def obj(z):
        return -np.sum(z[2::3])

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -1.0
        return g

    def xy_from(z):
        u = z[0::3]
        v = z[1::3]
        r = z[2::3]
        x = r + (1.0 - 2.0 * r) * u
        y = r + (1.0 - 2.0 * r) * v
        return x, y, r

    cons = []
    for i in range(n):
        for j in range(i + 1, n):
            def cp(z, i=i, j=j):
                x, y, r = xy_from(z)
                dx = x[i] - x[j]
                dy = y[i] - y[j]
                rs = r[i] + r[j]
                return dx * dx + dy * dy - rs * rs

            def cpg(z, i=i, j=j):
                x, y, r = xy_from(z)
                dx = x[i] - x[j]
                dy = y[i] - y[j]
                rs = r[i] + r[j]
                ax = 1.0 - 2.0 * r[i]
                bx = 1.0 - 2.0 * r[j]
                g = np.zeros_like(z)
                g[3 * i] = 2 * dx * ax
                g[3 * i + 1] = 2 * dy * ax
                g[3 * i + 2] = 2 * dx * (1.0 - 2.0 * z[3 * i]) + 2 * dy * (1.0 - 2.0 * z[3 * i + 1]) - 2 * rs
                g[3 * j] = 2 * dx * (-bx)
                g[3 * j + 1] = 2 * dy * (-bx)
                g[3 * j + 2] = 2 * dx * (-(1.0 - 2.0 * z[3 * j])) + 2 * dy * (-(1.0 - 2.0 * z[3 * j + 1])) - 2 * rs
                return g

            cons.append({'type': 'ineq', 'fun': cp, 'jac': cpg})

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.49))

    try:
        res = minimize(obj, x0, jac=obj_grad, method='SLSQP',
                       constraints=cons, bounds=bounds,
                       options={'maxiter': iters, 'ftol': ftol})
        z = res.x
    except Exception:
        z = x0

    x, y, r = xy_from(z)
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _repair(out, n, deflate=1e-11):
    out = out.copy()
    for _ in range(200):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
                sm = out[i, 2] + out[j, 2]
                if d < sm:
                    bad = True
                    ex = sm - d
                    out[i, 2] -= ex / 2 + 1e-12
                    out[j, 2] -= ex / 2 + 1e-12
        if not bad:
            break
    out[:, 2] = np.maximum(out[:, 2], 1e-12)
    out[:, 2] = out[:, 2] - deflate
    out[:, 2] = np.maximum(out[:, 2], 1e-12)
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    return out


def _repair_local(out):
    """Local violation repair: shrink only offending radii, no global deflation."""
    out = out.copy()
    n = out.shape[0]
    for _ in range(100):
        bad = False
        for i in range(n):
            x, y, r = out[i]
            v = max(r - x, x + r - 1.0, r - y, y + r - 1.0)
            if v > 0:
                bad = True
                out[i, 2] = r - v - 1e-13
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
                sm = out[i, 2] + out[j, 2]
                if d < sm:
                    bad = True
                    ex = sm - d
                    out[i, 2] -= ex / 2 + 1e-13
                    out[j, 2] -= ex / 2 + 1e-13
        if not bad:
            break
    out[:, 2] = np.maximum(out[:, 2], 1e-12)
    return out


def _valid(out, n):
    for i in range(n):
        x, y, r = out[i]
        if r <= 0:
            return False
        if x - r < 0 or x + r > 1 or y - r < 0 or y + r > 1:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
            if d < out[i, 2] + out[j, 2]:
                return False
    return True


def _uniform_scale_up(out, n, rounds=5):
    """Scale all radii up by the maximal uniform factor, keeping centres fixed."""
    out = out.copy()
    for _ in range(rounds):
        r = out[:, 2]
        x = out[:, 0]
        y = out[:, 1]
        lam = 1.0
        for i in range(n):
            if r[i] > 0:
                wd = min(x[i], 1.0 - x[i], y[i], 1.0 - y[i])
                lam = min(lam, wd / r[i])
        for i in range(n):
            for j in range(i + 1, n):
                rs = r[i] + r[j]
                if rs > 0:
                    d = np.hypot(x[i] - x[j], y[i] - y[j])
                    lam = min(lam, d / rs)
        if lam > 1.0 + 1e-15:
            out[:, 2] = r * lam * (1.0 - 1e-14)
        else:
            break
    return out


def _anchor_motif(cur, n, anchor, kind, rng):
    ax, ay = anchor
    dists = np.hypot(cur[:, 0] - ax, cur[:, 1] - ay)
    near = np.where(dists < 0.30)[0].tolist()
    order = np.argsort(dists)
    if len(near) < 12:
        for idx in order:
            if int(idx) not in near:
                near.append(int(idx))
            if len(near) >= 12:
                break
    elif len(near) > 20:
        near.sort(key=lambda i: dists[i])
        near = near[:20]
    del_set = set(near)
    keep_idx = [i for i in range(n) if i not in del_set]

    trial = cur.copy()
    present = [(cur[i, 0], cur[i, 1], cur[i, 2]) for i in keep_idx]

    ts = (0.12, 0.30, 0.50)
    if kind == 'corner':
        sx = 1.0 if ax < 0.5 else -1.0
        sy = 1.0 if ay < 0.5 else -1.0
        motif_pts = [(ax, ay)]
        for t in (0.15, 0.35, 0.55):
            motif_pts.append((ax + sx * t, ay))
            motif_pts.append((ax, ay + sy * t))
    else:
        if abs(ay) < 1e-9 or abs(ay - 1.0) < 1e-9:
            ny = 1.0 if ay < 0.5 else -1.0
            motif_pts = [(ax, ay)]
            for t in ts:
                motif_pts.append((ax - t, ay))
                motif_pts.append((ax + t, ay))
            for t in ts:
                motif_pts.append((ax, ay + ny * t))
        else:
            nx = 1.0 if ax < 0.5 else -1.0
            motif_pts = [(ax, ay)]
            for t in ts:
                motif_pts.append((ax, ay - t))
                motif_pts.append((ax, ay + t))
            for t in ts:
                motif_pts.append((ax + nx * t, ay))

    ins_order = list(near)
    rng.shuffle(ins_order)
    mi = 0
    for i in ins_order:
        if mi < len(motif_pts):
            px, py = motif_pts[mi]
            mi += 1
            if px <= 0.0:
                px = 0.0
            if px >= 1.0:
                px = 1.0
            if py <= 0.0:
                py = 0.0
            if py >= 1.0:
                py = 1.0
            rr = _feasible_radius(px, py, present, n)
            if rr <= 0:
                rr = 1e-6
            trial[i, 0] = px
            trial[i, 1] = py
            trial[i, 2] = rr
            present.append((px, py, rr))
        else:
            ox, oy, orad = cur[i]
            cap = 1.2 * orad
            best_r = -1.0
            best_c = (ox, oy)
            for kk in range(2000):
                if kk < 1000:
                    px = ox + rng.normal(0, 0.05)
                    py = oy + rng.normal(0, 0.05)
                else:
                    px = rng.uniform(0.02, 0.98)
                    py = rng.uniform(0.02, 0.98)
                if px <= 0 or px >= 1 or py <= 0 or py >= 1:
                    continue
                rr = _feasible_radius(px, py, present, n)
                if rr > cap:
                    rr = cap
                if rr > best_r:
                    best_r = rr
                    best_c = (px, py)
            if best_r <= 0:
                best_r = 1e-6
            trial[i, 0] = best_c[0]
            trial[i, 1] = best_c[1]
            trial[i, 2] = best_r
            present.append((best_c[0], best_c[1], best_r))

    return trial


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    deadline = t0 + budget_seconds - 1.0

    if start is not None and np.asarray(start).shape == (n, 3):
        cur = np.array(start, dtype=float)
    else:
        k = 6
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        cur = np.array([[x, y, 0.08] for (x, y) in pts])

    cur = _repair(cur, n)
    best = cur.copy()
    best_score = np.sum(best[:, 2])

    rng = np.random.default_rng(12345)
    anchors = [
        ((0.0, 0.0), 'corner'),
        ((1.0, 0.0), 'corner'),
        ((0.0, 1.0), 'corner'),
        ((1.0, 1.0), 'corner'),
        ((0.5, 0.0), 'edge'),
        ((0.5, 1.0), 'edge'),
        ((0.0, 0.5), 'edge'),
        ((1.0, 0.5), 'edge'),
    ]
    ai = 0

    while time.process_time() < deadline:
        anchor, kind = anchors[ai % len(anchors)]
        ai += 1

        trial = _anchor_motif(cur, n, anchor, kind, rng)
        trial = _repair(trial, n)
        if time.process_time() < deadline:
            try:
                polished = _slsqp_polish(trial, n, 350)
                polished = _repair(polished, n)
            except Exception:
                polished = trial
        else:
            polished = trial

        if _valid(polished, n):
            sc = np.sum(polished[:, 2])
            if sc > best_score + 1e-12:
                best = polished.copy()
                best_score = sc
                cur = polished.copy()
            else:
                cur = best.copy()
        else:
            cur = best.copy()

    fallback = _repair(best, n)
    final = fallback

    try:
        polished = _slsqp_polish(best, n, 5000, ftol=1e-18)
        if _valid(polished, n):
            candidate = polished
        else:
            candidate = _repair_local(polished)
        if _valid(candidate, n) and np.sum(candidate[:, 2]) >= np.sum(fallback[:, 2]):
            final = candidate
    except Exception:
        final = fallback

    # Experiment: uniform scale-up of radii at fixed centres.
    try:
        scaled = _uniform_scale_up(final, n, rounds=5)
        if _valid(scaled, n) and np.sum(scaled[:, 2]) >= np.sum(final[:, 2]):
            final = scaled
    except Exception:
        pass

    return final

import numpy as np
import time
from scipy.optimize import minimize


def _feasible_radius(cx, cy, present, n):
    r = min(cx, 1.0 - cx, cy, 1.0 - cy)
    for (px, py, pr) in present:
        d = np.hypot(cx - px, cy - py)
        r = min(r, d - pr)
    return r


def _slsqp_polish(s, n, iters, ftol=1e-14):
    r0 = np.clip(s[:, 2], 1e-6, 0.49)
    denom = 1.0 - 2.0 * r0
    denom = np.where(np.abs(denom) < 1e-9, 1e-9, denom)
    u0 = np.clip((s[:, 0] - r0) / denom, 0.0, 1.0)
    v0 = np.clip((s[:, 1] - r0) / denom, 0.0, 1.0)

    x0 = np.zeros(3 * n)
    x0[0::3] = u0
    x0[1::3] = v0
    x0[2::3] = r0

    def obj(z):
        return -np.sum(z[2::3])

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -1.0
        return g

    def xy_from(z):
        u = z[0::3]
        v = z[1::3]
        r = z[2::3]
        x = r + (1.0 - 2.0 * r) * u
        y = r + (1.0 - 2.0 * r) * v
        return x, y, r

    cons = []
    for i in range(n):
        for j in range(i + 1, n):
            def cp(z, i=i, j=j):
                x, y, r = xy_from(z)
                dx = x[i] - x[j]
                dy = y[i] - y[j]
                rs = r[i] + r[j]
                return dx * dx + dy * dy - rs * rs

            def cpg(z, i=i, j=j):
                x, y, r = xy_from(z)
                dx = x[i] - x[j]
                dy = y[i] - y[j]
                rs = r[i] + r[j]
                ax = 1.0 - 2.0 * r[i]
                bx = 1.0 - 2.0 * r[j]
                g = np.zeros_like(z)
                g[3 * i] = 2 * dx * ax
                g[3 * i + 1] = 2 * dy * ax
                g[3 * i + 2] = 2 * dx * (1.0 - 2.0 * z[3 * i]) + 2 * dy * (1.0 - 2.0 * z[3 * i + 1]) - 2 * rs
                g[3 * j] = 2 * dx * (-bx)
                g[3 * j + 1] = 2 * dy * (-bx)
                g[3 * j + 2] = 2 * dx * (-(1.0 - 2.0 * z[3 * j])) + 2 * dy * (-(1.0 - 2.0 * z[3 * j + 1])) - 2 * rs
                return g

            cons.append({'type': 'ineq', 'fun': cp, 'jac': cpg})

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.49))

    try:
        res = minimize(obj, x0, jac=obj_grad, method='SLSQP',
                       constraints=cons, bounds=bounds,
                       options={'maxiter': iters, 'ftol': ftol})
        z = res.x
    except Exception:
        z = x0

    x, y, r = xy_from(z)
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


