def _contact_components(cur, n, tol=1e-7):
    """Union-find over contact graph (d_ij - r_i - r_j < tol)."""
    parent = list(range(n))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(cur[i, 0] - cur[j, 0], cur[i, 1] - cur[j, 1])
            if d - cur[i, 2] - cur[j, 2] < tol:
                union(i, j)

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)
    return list(groups.values())


def _wall_contacts(cur, n, tol=1e-7):
    """Return list of (i, wx, wy) for circles touching a wall, with the wall point."""
    out = []
    for i in range(n):
        x, y, r = cur[i]
        if abs(x - r) < tol:
            out.append((i, 0.0, y))
        if abs(x + r - 1.0) < tol:
            out.append((i, 1.0, y))
        if abs(y - r) < tol:
            out.append((i, x, 0.0))
        if abs(y + r - 1.0) < tol:
            out.append((i, x, 1.0))
    return out


def _rotate_cluster(cur, cluster, pivot, angle):
    """Rotate centres of cluster about pivot by angle; radii unchanged."""
    out = cur.copy()
    px, py = pivot
    ca, sa = np.cos(angle), np.sin(angle)
    for i in cluster:
        dx = cur[i, 0] - px
        dy = cur[i, 1] - py
        out[i, 0] = px + ca * dx - sa * dy
        out[i, 1] = py + sa * dx + ca * dy
    return out


