        ((0.0, 0.0), 'corner'),
        ((1.0, 0.0), 'corner'),
        ((0.0, 1.0), 'corner'),
        ((1.0, 1.0), 'corner'),
        ((0.5, 0.0), 'edge'),
        ((0.5, 1.0), 'edge'),
        ((0.0, 0.5), 'edge'),
        ((1.0, 0.5), 'edge'),
    ]
    ai = 0

    while time.process_time() < deadline:
        anchor, kind = anchors[ai % len(anchors)]
        ai += 1

        trial = _anchor_motif(cur, n, anchor, kind, rng)
        trial = _repair(trial, n)
        if time.process_time() < deadline:
            try:
                polished = _slsqp_polish(trial, n, 350)
                polished = _repair(polished, n)
            except Exception:
                polished = trial
        else:
            polished = trial

        if _valid(polished, n):
            sc = np.sum(polished[:, 2])
            if sc > best_score + 1e-12:
                best = polished.copy()
                best_score = sc
                cur = polished.copy()
            else:
                cur = best.copy()
        else:
            cur = best.copy()

    fallback = _repair(best, n)
    final = fallback

    try:
        polished = _slsqp_polish(best, n, 5000, ftol=1e-18)
        if _valid(polished, n):
            candidate = polished
        else:
            candidate = _repair_local(polished)
        if _valid(candidate, n) and np.sum(candidate[:, 2]) >= np.sum(fallback[:, 2]):
            final = candidate
    except Exception:
        final = fallback

    # Experiment: rigid cluster rotation about wall contacts.
    # Use remaining time budget.
    try:
        work = final.copy()
        work_score = np.sum(work[:, 2])
        angles = (0.01, -0.01, 0.02, -0.02)
        # Reserve a small margin for final repair/return.
        rot_deadline = t0 + budget_seconds - 0.3
        while time.process_time() < rot_deadline:
            comps = _contact_components(work, n)
            # candidate clusters: 6-12 circles including a wall-touching circle
            wall = _wall_contacts(work, n)
            if not wall:
                break
            # map circle -> wall points
            wall_map = {}
            for (i, wx, wy) in wall:
                wall_map.setdefault(i, []).append((wx, wy))
            candidates = []
            for comp in comps:
                if 6 <= len(comp) <= 12:
                    wall_in = [i for i in comp if i in wall_map]
                    if wall_in:
                        candidates.append((comp, wall_in))
            if not candidates:
                # try expanding: pick any wall-touching circle's component if smaller
                # or just break to avoid infinite loop
                break
            comp, wall_in = candidates[rng.integers(len(candidates))]
            wi = wall_in[rng.integers(len(wall_in))]
            pivot = wall_map[wi][rng.integers(len(wall_map[wi]))]
            # ensure pivot is a genuine wall point for wi
            px, py = pivot
            # rotate
            for ang in angles:
                if time.process_time() >= rot_deadline:
                    break
                trial = _rotate_cluster(work, comp, (px, py), ang)
                trial = _repair_local(trial)
                if not _valid(trial, n):
                    continue
                try:
                    pol = _slsqp_polish(trial, n, 300)
                    pol = _repair_local(pol)
                except Exception:
                    pol = trial
                if _valid(pol, n):
                    sc = np.sum(pol[:, 2])
                    if sc > work_score + 1e-12:
                        work = pol
                        work_score = sc
                        break
            else:
                # no improvement; continue trying other clusters
                pass
        if work_score > np.sum(final[:, 2]) and _valid(work, n):
            final = work
    except Exception:
        pass

    return final

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_radius(cx, cy, present, n):
    r = min(cx, 1.0 - cx, cy, 1.0 - cy)
    for (px, py, pr) in present:
        d = np.hypot(cx - px, cy - py)
        r = min(r, d - pr)
    return r


def _slsqp_polish(s, n, iters, ftol=1e-14):
    r0 = np.clip(s[:, 2], 1e-6, 0.49)
    denom = 1.0 - 2.0 * r0
    denom = np.where(np.abs(denom) < 1e-9, 1e-9, denom)
    u0 = np.clip((s[:, 0] - r0) / denom, 0.0, 1.0)
    v0 = np.clip((s[:, 1] - r0) / denom, 0.0, 1.0)

    x0 = np.zeros(3 * n)
    x0[0::3] = u0
    x0[1::3] = v0
    x0[2::3] = r0

    def obj(z):
        return -np.sum(z[2::3])

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -1.0
        return g

    def xy_from(z):
        u = z[0::3]
        v = z[1::3]
        r = z[2::3]
        x = r + (1.0 - 2.0 * r) * u
        y = r + (1.0 - 2.0 * r) * v
        return x, y, r

    cons = []
    for i in range(n):
        for j in range(i + 1, n):
            def cp(z, i=i, j=j):
                x, y, r = xy_from(z)
                dx = x[i] - x[j]
                dy = y[i] - y[j]
                rs = r[i] + r[j]
                return dx * dx + dy * dy - rs * rs

            def cpg(z, i=i, j=j):
                x, y, r = xy_from(z)
                dx = x[i] - x[j]
                dy = y[i] - y[j]
                rs = r[i] + r[j]
                ax = 1.0 - 2.0 * r[i]
                bx = 1.0 - 2.0 * r[j]
                g = np.zeros_like(z)
                g[3 * i] = 2 * dx * ax
                g[3 * i + 1] = 2 * dy * ax
                g[3 * i + 2] = 2 * dx * (1.0 - 2.0 * z[3 * i]) + 2 * dy * (1.0 - 2.0 * z[3 * i + 1]) - 2 * rs
                g[3 * j] = 2 * dx * (-bx)
                g[3 * j + 1] = 2 * dy * (-bx)
                g[3 * j + 2] = 2 * dx * (-(1.0 - 2.0 * z[3 * j])) + 2 * dy * (-(1.0 - 2.0 * z[3 * j + 1])) - 2 * rs
                return g

            cons.append({'type': 'ineq', 'fun': cp, 'jac': cpg})

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.49))

    try:
        res = minimize(obj, x0, jac=obj_grad, method='SLSQP',
                       constraints=cons, bounds=bounds,
                       options={'maxiter': iters, 'ftol': ftol})
        z = res.x
    except Exception:
        z = x0

    x, y, r = xy_from(z)
    r = np.maximum(r, 1e-9)
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)
    return np.column_stack([x, y, r])


def _repair(out, n, deflate=1e-11):
    out = out.copy()
    for _ in range(200):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
                sm = out[i, 2] + out[j, 2]
                if d < sm:
                    bad = True
                    ex = sm - d
                    out[i, 2] -= ex / 2 + 1e-12
                    out[j, 2] -= ex / 2 + 1e-12
        if not bad:
            break
    out[:, 2] = np.maximum(out[:, 2], 1e-12)
    out[:, 2] = out[:, 2] - deflate
    out[:, 2] = np.maximum(out[:, 2], 1e-12)
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    return out


def _repair_local(out):
    out = out.copy()
    n = out.shape[0]
    for _ in range(100):
        bad = False
        for i in range(n):
            x, y, r = out[i]
            v = max(r - x, x + r - 1.0, r - y, y + r - 1.0)
            if v > 0:
                bad = True
                out[i, 2] = r - v - 1e-13
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
                sm = out[i, 2] + out[j, 2]
                if d < sm:
                    bad = True
                    ex = sm - d
                    out[i, 2] -= ex / 2 + 1e-13
                    out[j, 2] -= ex / 2 + 1e-13
        if not bad:
            break
    out[:, 2] = np.maximum(out[:, 2], 1e-12)
    return out


def _valid(out, n):
    for i in range(n):
        x, y, r = out[i]
        if r <= 0:
            return False
        if x - r < 0 or x + r > 1 or y - r < 0 or y + r > 1:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(out[i, 0] - out[j, 0], out[i, 1] - out[j, 1])
            if d < out[i, 2] + out[j, 2]:
                return False
    return True


def _anchor_motif(cur, n, anchor, kind, rng):
    ax, ay = anchor
    dists = np.hypot(cur[:, 0] - ax, cur[:, 1] - ay)
    near = np.where(dists < 0.30)[0].tolist()
    order = np.argsort(dists)
    if len(near) < 12:
        for idx in order:
            if int(idx) not in near:
                near.append(int(idx))
            if len(near) >= 12:
                break
    elif len(near) > 20:
        near.sort(key=lambda i: dists[i])
        near = near[:20]
    del_set = set(near)
    keep_idx = [i for i in range(n) if i not in del_set]

    trial = cur.copy()
    present = [(cur[i, 0], cur[i, 1], cur[i, 2]) for i in keep_idx]

    ts = (0.12, 0.30, 0.50)
    if kind == 'corner':
        sx = 1.0 if ax < 0.5 else -1.0
        sy = 1.0 if ay < 0.5 else -1.0
        motif_pts = [(ax, ay)]
        for t in (0.15, 0.35, 0.55):
            motif_pts.append((ax + sx * t, ay))
            motif_pts.append((ax, ay + sy * t))
    else:
        if abs(ay) < 1e-9 or abs(ay - 1.0) < 1e-9:
            ny = 1.0 if ay < 0.5 else -1.0
            motif_pts = [(ax, ay)]
            for t in ts:
                motif_pts.append((ax - t, ay))
                motif_pts.append((ax + t, ay))
            for t in ts:
                motif_pts.append((ax, ay + ny * t))
        else:
            nx = 1.0 if ax < 0.5 else -1.0
            motif_pts = [(ax, ay)]
            for t in ts:
                motif_pts.append((ax, ay - t))
                motif_pts.append((ax, ay + t))
            for t in ts:
                motif_pts.append((ax + nx * t, ay))

    ins_order = list(near)
    rng.shuffle(ins_order)
    mi = 0
    for i in ins_order:
        if mi < len(motif_pts):
            px, py = motif_pts[mi]
            mi += 1
            if px <= 0.0:
                px = 0.0
            if px >= 1.0:
                px = 1.0
            if py <= 0.0:
                py = 0.0
            if py >= 1.0:
                py = 1.0
            rr = _feasible_radius(px, py, present, n)
            if rr <= 0:
                rr = 1e-6
            trial[i, 0] = px
            trial[i, 1] = py
            trial[i, 2] = rr
            present.append((px, py, rr))
        else:
            ox, oy, orad = cur[i]
            cap = 1.2 * orad
            best_r = -1.0
            best_c = (ox, oy)
            for kk in range(2000):
                if kk < 1000:
                    px = ox + rng.normal(0, 0.05)
                    py = oy + rng.normal(0, 0.05)
                else:
                    px = rng.uniform(0.02, 0.98)
                    py = rng.uniform(0.02, 0.98)
                if px <= 0 or px >= 1 or py <= 0 or py >= 1:
                    continue
                rr = _feasible_radius(px, py, present, n)
                if rr > cap:
                    rr = cap
                if rr > best_r:
                    best_r = rr
                    best_c = (px, py)
            if best_r <= 0:
                best_r = 1e-6
            trial[i, 0] = best_c[0]
            trial[i, 1] = best_c[1]
            trial[i, 2] = best_r
            present.append((best_c[0], best_c[1], best_r))

    return trial


def _lp_radii(centers, n, margin=1e-12):
    """Given fixed centers (n,2), solve LP maximizing sum r subject to
    r_i <= dist to walls, r_i + r_j <= dist_ij, r_i >= 0.
    Returns radii array or None."""
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    # wall constraints: r_i <= x_i, r_i <= 1-x_i, r_i <= y_i, r_i <= 1-y_i
    for i in range(n):
        x, y = centers[i]
        for lim in (x, 1.0 - x, y, 1.0 - y):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(lim - margin, 0.0))
    # pair constraints: r_i + r_j <= d_ij
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d - margin, 0.0))
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=[(0.0, None)] * n, method='highs')
        if not res.success:
            return None
        return np.maximum(res.x, 0.0)
    except Exception:
        return None


def _coord_descent_lp(cur, n, rng, trials=200, sigma=0.01):
    centers = cur[:, :2].copy()
    radii = _lp_radii(centers, n)
    if radii is None:
        return cur.copy()
    best_centers = centers.copy()
    best_radii = radii.copy()
    best_sum = np.sum(radii)
    for _ in range(trials):
        i = int(rng.integers(n))
        new_centers = best_centers.copy()
        nx = new_centers[i, 0] + rng.normal(0, sigma)
        ny = new_centers[i, 1] + rng.normal(0, sigma)
        new_centers[i, 0] = min(max(nx, 0.0), 1.0)
        new_centers[i, 1] = min(max(ny, 0.0), 1.0)
        new_radii = _lp_radii(new_centers, n)
        if new_radii is None:
            continue
        s = np.sum(new_radii)
        if s > best_sum + 1e-14:
            best_sum = s
            best_centers = new_centers
            best_radii = new_radii
    return np.column_stack([best_centers[:, 0], best_centers[:, 1], best_radii])


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    deadline = t0 + budget_seconds - 1.0

    if start is not None and np.asarray(start).shape == (n, 3):
        cur = np.array(start, dtype=float)
    else:
        k = 6
        pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:n]
        cur = np.array([[x, y, 0.08] for (x, y) in pts])

    cur = _repair(cur, n)
    best = cur.copy()
    best_score = np.sum(best[:, 2])

    rng = np.random.default_rng(12345)
    anchors = [
        ((0.0, 0.0), 'corner'),
        ((1.0, 0.0), 'corner'),
        ((0.0, 1.0), 'corner'),
        ((1.0, 1.0), 'corner'),
        ((0.5, 0.0), 'edge'),
        ((0.5, 1.0), 'edge'),
        ((0.0, 0.5), 'edge'),
        ((1.0, 0.5), 'edge'),
    ]
    ai = 0

    while time.process_time() < deadline:
        anchor, kind = anchors[ai % len(anchors)]
        ai += 1

        trial = _anchor_motif(cur, n, anchor, kind, rng)
        trial = _repair(trial, n)
        if time.process_time() < deadline:
            try:
                polished = _slsqp_polish(trial, n, 350)
                polished = _repair(polished, n)
            except Exception:
                polished = trial
        else:
            polished = trial

        if _valid(polished, n):
            sc = np.sum(polished[:, 2])
            if sc > best_score + 1e-12:
                best = polished.copy()
                best_score = sc
                cur = polished.copy()
            else:
                cur = best.copy()
        else:
            cur = best.copy()

    fallback = _repair(best, n)
    final = fallback

    try:
        polished = _slsqp_polish(best, n, 5000, ftol=1e-18)
        if _valid(polished, n):
            candidate = polished
        else:
            candidate = _repair_local(polished)
        if _valid(candidate, n) and np.sum(candidate[:, 2]) >= np.sum(fallback[:, 2]):
            final = candidate
    except Exception:
        final = fallback

    # Experiment: coordinate-descent in centre space with exact LP radii.
    try:
        if time.process_time() < deadline:
            lp_pt = _coord_descent_lp(final, n, rng, trials=200, sigma=0.01)
            lp_pt = _repair_local(lp_pt)
            if _valid(lp_pt, n) and np.sum(lp_pt[:, 2]) > np.sum(final[:, 2]):
                final = lp_pt
            if time.process_time() < deadline:
                try:
                    pol = _slsqp_polish(final, n, 2000, ftol=1e-18)
                    pol = _repair_local(pol)
                    if _valid(pol, n) and np.sum(pol[:, 2]) > np.sum(final[:, 2]):
                        final = pol
                except Exception:
                    pass
    except Exception:
        pass

    return final
